//! Points where statrs is known to be wrong, one list per finding.
//!
//! Each list is exact: CI fails if a listed point stops failing (fixed
//! upstream: update the finding) or a failing point is not listed. The
//! lists were produced from the harness output for the pinned version;
//! the findings files explain them.

